examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true }, variant = MonarchButtonVariant.Primary)
if (open) {
    MonarchDialog(onDismissRequest = { open = false }, title = null, paneTitle = "Join Weekly planning") {
        @OptIn(ExperimentalMonarchApi::class)
        MonarchPreJoinLobby(
            micOn = mic,
            onMicOnChange = { mic = it },
            onJoin = { withMic, withCamera -> join(withMic, withCamera) },
            icon = { control, on ->
                val glyph = when (control) {
                    MonarchCallControl.Microphone -> if (on) SampleIcons.Mic else SampleIcons.MicOff
                    MonarchCallControl.Camera -> if (on) SampleIcons.Video else SampleIcons.VideoOff
                    MonarchCallControl.ShareScreen -> SampleIcons.ScreenShare
                    MonarchCallControl.RaiseHand -> SampleIcons.RaiseHand
                    MonarchCallControl.React -> SampleIcons.React
                    MonarchCallControl.More -> SampleIcons.More
                    MonarchCallControl.Leave -> SampleIcons.CallEnd
                }
                MonarchIcon(glyph, contentDescription = null)
            },
            cameraOn = camera,
            onCameraOnChange = { camera = it },
            audioLevel = 0.3f, // Measured by the app, for example with AudioRecord.
            participants = listOf(
                MonarchPreJoinLobbyParticipant({{participants.0}}),
                MonarchPreJoinLobbyParticipant({{participants.1}}),
                MonarchPreJoinLobbyParticipant({{participants.2}}),
            ),
            labels = MonarchPreJoinLobbyLabels(title = {{title}}, cameraOff = {{cameraOff}}, cancel = {{cancel}}, join = {{join}}),
            onCancel = { /* Close the lobby. */ },
            devices = {
                MonarchDevicePicker(
                    microphone = microphone,
                    onMicrophoneChange = { microphone = it },
                    microphones = listOf(MonarchDevicePickerDevice({{microphone.id}}, {{microphone.label}})),
                    camera = cameraDevice,
                    onCameraChange = { cameraDevice = it },
                    cameras = listOf(MonarchDevicePickerDevice({{camera.id}}, {{camera.label}})),
                    size = MonarchDevicePickerSize.Sm,
                )
            },
        ) {
            // The app's CameraX PreviewView, through AndroidView.
        }
    }
}

